; >S:KEY-SCAN; PUT "KEY-SCAN";; THIS WILL BE CALLED FROM THE; JOYSTICK READ ROUTINE IF IT; FINDS THERE IS NO JOYSTICK; MOVEMENT,; IT WILL THEN CLEAR OR SET THE; APPROPRIATE VARIABLES IF KEYS; ARE PRESSED;; NOTE IT WILL SET OR CLEAR; JMOVE AS APPROPRIATE;;;KEY;LDA #0STA JMOVE;LDX #4;SCAN1;LDA BTD,XLDY RWD,X;JSR KEYIT;ROR JLEFT,X;DEXBPL SCAN1;RTS;; LEFT  = 'Z'; RIGHT = 'X'; UP    = ';'; DOWN  = '/'; FIRE  = 'SPACE';KEYIT;STY $FD30STY $FF08AND $FF08;BNE RTTY;LDA #$01STA JMOVESEC;RTS;RTTY;CLC;RTS;;BTD;;      L   R   U   D   F;.BYTE $10,$80,$04,$80,$10;RWD;.BYTE $FD,$FB,$BF,$BF,$7F;.END